using System;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using Codice.Characters;
public static class BuildClassModels{
 const string root="Assets/Resources/Presentation/Classes";static string folder;static GameObject actor;static Animator rig;
 static Material Mat(string name,Color color,float metal=0){var path=folder+"/"+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(m,path);}m.SetColor("_BaseColor",color);m.SetFloat("_Metallic",metal);m.SetFloat("_Smoothness",metal>.1f?.32f:.12f);return m;}
 static Vector3 Pos(HumanBodyBones b)=>rig.GetBoneTransform(b).position;
 static void MeshPart(string name,HumanBodyBones bone,Vector3[] vertices,int[] triangles,Material material){var mesh=new Mesh{name=name};mesh.vertices=vertices;mesh.triangles=triangles;mesh.RecalculateNormals();mesh.RecalculateBounds();var path=folder+"/"+name+".asset";var prior=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(prior){prior.Clear();prior.vertices=mesh.vertices;prior.triangles=mesh.triangles;prior.RecalculateNormals();prior.RecalculateBounds();prior.UploadMeshData(false);EditorUtility.SetDirty(prior);UnityEngine.Object.DestroyImmediate(mesh);mesh=prior;}else AssetDatabase.CreateAsset(mesh,path);var go=new GameObject(name,typeof(MeshFilter),typeof(MeshRenderer));go.transform.SetParent(actor.transform,false);go.GetComponent<MeshFilter>().sharedMesh=mesh;go.GetComponent<MeshRenderer>().sharedMaterial=material;go.transform.SetParent(rig.GetBoneTransform(bone),true);}
 // Faceted shells use rest-pose coordinates and follow one bone; no new skeleton or competing animator.
 static void Shell(string name,HumanBodyBones bone,Vector3 from,Vector3 to,float r0,float r1,float depth,Material material,int sides=10){var axis=(to-from).normalized;var right=Vector3.Cross(axis,Vector3.forward).normalized;if(right.sqrMagnitude<.1f)right=Vector3.right;var front=Vector3.Cross(right,axis).normalized;var v=new List<Vector3>();var tris=new List<int>();for(int j=0;j<3;j++)for(int i=0;i<sides;i++){float angle=i*Mathf.PI*2/sides;float r=j==1?Mathf.Max(r0,r1)*1.05f:j==0?r0:r1;v.Add(Vector3.Lerp(from,to,j*.5f)+right*Mathf.Cos(angle)*r+front*Mathf.Sin(angle)*r*depth);}for(int j=0;j<2;j++)for(int i=0;i<sides;i++){int a=j*sides+i,b=j*sides+(i+1)%sides,c=b+sides,d=a+sides;tris.AddRange(new[]{a,c,b,a,d,c});}int bottom=v.Count;v.Add(from);int top=v.Count;v.Add(to);for(int i=0;i<sides;i++){tris.AddRange(new[]{bottom,(i+1)%sides,i,top,2*sides+i,2*sides+(i+1)%sides});}MeshPart(name,bone,v.ToArray(),tris.ToArray(),material);}
 static void Plate(string name,HumanBodyBones bone,Vector3 center,Vector3 size,Material material){var x=size.x*.5f;var y=size.y*.5f;var z=size.z*.5f;var v=new[]{new Vector3(-x,y,-z),new Vector3(x,y,-z),new Vector3(x,-y*.55f,-z),new Vector3(0,-y,-z),new Vector3(-x,-y*.55f,-z),new Vector3(-x,y,z),new Vector3(x,y,z),new Vector3(x,-y*.55f,z),new Vector3(0,-y,z),new Vector3(-x,-y*.55f,z)}.Select(p=>p+center).ToArray();var t=new List<int>();for(int i=1;i<4;i++){t.AddRange(new[]{0,i+1,i,5,5+i,6+i});}for(int i=0;i<5;i++){int n=(i+1)%5;t.AddRange(new[]{i,n,5+n,i,5+n,5+i});}MeshPart(name,bone,v,t.ToArray(),material);}
 public static string Run(){
  System.IO.Directory.CreateDirectory(root);AssetDatabase.Refresh();
  foreach(PlayerClass role in Enum.GetValues(typeof(PlayerClass))){folder=root+"/"+role;System.IO.Directory.CreateDirectory(folder);AssetDatabase.Refresh();actor=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Resources/Presentation/Human/HumanPlayer.prefab"));actor.name=role+" · Peregrino de ceniza";rig=actor.GetComponentInChildren<Animator>();rig.enabled=false;
   Color accent=role switch{PlayerClass.Warrior=>new Color(.28f,.045f,.035f),PlayerClass.Tank=>new Color(.11f,.18f,.17f),PlayerClass.Mage=>new Color(.16f,.08f,.25f),PlayerClass.Archer=>new Color(.12f,.19f,.12f),PlayerClass.Shinobi=>new Color(.07f,.10f,.16f),_=>new Color(.32f,.07f,.035f)};
   var cloth=Mat("Tela",accent);var dark=Mat("Cuero carbon",new Color(.045f,.04f,.038f));var steel=Mat("Acero envejecido",role==PlayerClass.Tank?new Color(.17f,.20f,.22f):new Color(.25f,.25f,.23f),.75f);var trim=Mat("Laton antiguo",new Color(.38f,.27f,.12f),.6f);foreach(var renderer in actor.GetComponentsInChildren<SkinnedMeshRenderer>())renderer.sharedMaterials=renderer.sharedMaterials.Select(_=>dark).ToArray();
   bool heavy=role==PlayerClass.Warrior||role==PlayerClass.Tank;float bulk=role==PlayerClass.Tank?1.2f:1;
   Shell("Coraza",HumanBodyBones.Chest,Pos(HumanBodyBones.Chest)+Vector3.down*.20f,Pos(HumanBodyBones.Chest)+Vector3.up*.20f,.22f*bulk,.255f*bulk,.78f,heavy?steel:cloth);
   Shell("Cinturon",HumanBodyBones.Hips,Pos(HumanBodyBones.Hips)+Vector3.up*.08f,Pos(HumanBodyBones.Hips)+Vector3.up*.14f,.205f,.19f,.85f,dark);
   Plate("Hebilla",HumanBodyBones.Hips,Pos(HumanBodyBones.Hips)+new Vector3(0,.11f,.13f),new Vector3(.075f,.075f,.025f),trim);
   if(heavy)Plate("Peto grabado",HumanBodyBones.Chest,Pos(HumanBodyBones.Chest)+new Vector3(0,.06f,.215f),new Vector3(.22f,.24f,.025f),trim);
   foreach(bool left in new[]{true,false}){var arm=left?HumanBodyBones.LeftUpperArm:HumanBodyBones.RightUpperArm;var fore=left?HumanBodyBones.LeftLowerArm:HumanBodyBones.RightLowerArm;var hand=left?HumanBodyBones.LeftHand:HumanBodyBones.RightHand;var thigh=left?HumanBodyBones.LeftUpperLeg:HumanBodyBones.RightUpperLeg;var shin=left?HumanBodyBones.LeftLowerLeg:HumanBodyBones.RightLowerLeg;var foot=left?HumanBodyBones.LeftFoot:HumanBodyBones.RightFoot;string side=left?"L":"R";
    Shell("Brazal "+side,fore,Vector3.Lerp(Pos(fore),Pos(hand),.2f),Vector3.Lerp(Pos(fore),Pos(hand),.85f),.085f,.062f,1,heavy?steel:dark);
    Shell("Greba "+side,shin,Vector3.Lerp(Pos(shin),Pos(foot),.14f),Vector3.Lerp(Pos(shin),Pos(foot),.85f),.085f,.06f,.9f,heavy?steel:dark);
    Shell("Muslera "+side,thigh,Vector3.Lerp(Pos(thigh),Pos(shin),.12f),Vector3.Lerp(Pos(thigh),Pos(shin),.72f),.135f,.105f,.95f,heavy?steel:cloth);
    if(heavy||role==PlayerClass.Berserker||left&&role==PlayerClass.Archer)Shell("Hombrera "+side,arm,Pos(arm)+new Vector3(left?.015f:-.015f,.015f,0),Vector3.Lerp(Pos(arm),Pos(fore),.48f)+Vector3.up*.015f,.125f*bulk,.09f*bulk,.92f,steel,8);
    if(role==PlayerClass.Mage||role==PlayerClass.Archer||role==PlayerClass.Shinobi)Plate("Faldon articulado "+side,thigh,Vector3.Lerp(Pos(thigh),Pos(shin),.35f)+new Vector3(0,0,-.10f),new Vector3(.18f,role==PlayerClass.Mage?.52f:.32f,.035f),cloth);
   }
   var head=Pos(HumanBodyBones.Head);
   if(heavy){Shell("Yelmo",HumanBodyBones.Head,head+Vector3.down*.02f,head+Vector3.up*.24f,.15f,.12f,1.12f,steel,10);Plate("Visor",HumanBodyBones.Head,head+new Vector3(0,.105f,.19f),new Vector3(.19f,.045f,.025f),dark);Plate("Nasal",HumanBodyBones.Head,head+new Vector3(0,.065f,.215f),new Vector3(.025f,.12f,.02f),trim);}
   else{Shell("Capucha",HumanBodyBones.Head,head+Vector3.down*.055f,head+Vector3.up*(role==PlayerClass.Mage?.29f:.22f),.16f,.12f,1.12f,cloth,10);Plate("Mascara",HumanBodyBones.Head,head+new Vector3(0,.055f,.195f),new Vector3(.17f,.15f,.025f),dark);Plate("Mirada",HumanBodyBones.Head,head+new Vector3(0,.12f,.218f),new Vector3(.13f,.018f,.015f),trim);}
   if(role==PlayerClass.Shinobi)Plate("Bufanda",HumanBodyBones.Chest,Pos(HumanBodyBones.Chest)+new Vector3(.12f,.02f,-.15f),new Vector3(.12f,.38f,.025f),cloth);
   if(role==PlayerClass.Mage){Shell("Collar arcano",HumanBodyBones.Chest,Pos(HumanBodyBones.Chest)+Vector3.up*.14f,Pos(HumanBodyBones.Chest)+Vector3.up*.23f,.19f,.13f,.7f,trim);Plate("Sello arcano",HumanBodyBones.Chest,Pos(HumanBodyBones.Chest)+new Vector3(0,.025f,.21f),new Vector3(.08f,.14f,.025f),trim);}
   if(role==PlayerClass.Berserker){Plate("Cresta",HumanBodyBones.Head,head+new Vector3(0,.25f,0),new Vector3(.045f,.19f,.18f),steel);Plate("Faja carmesi",HumanBodyBones.Hips,Pos(HumanBodyBones.Hips)+new Vector3(0,-.10f,.14f),new Vector3(.19f,.25f,.035f),cloth);}
   foreach(bool left in new[]{true,false}){var arm=left?HumanBodyBones.LeftUpperArm:HumanBodyBones.RightUpperArm;var fore=left?HumanBodyBones.LeftLowerArm:HumanBodyBones.RightLowerArm;var thigh=left?HumanBodyBones.LeftUpperLeg:HumanBodyBones.RightUpperLeg;var shin=left?HumanBodyBones.LeftLowerLeg:HumanBodyBones.RightLowerLeg;string side=left?"L":"R";
    Shell("Manga "+side,arm,Vector3.Lerp(Pos(arm),Pos(fore),-.10f),Vector3.Lerp(Pos(arm),Pos(fore),.72f),heavy?.14f:.115f,.085f,.95f,heavy?steel:cloth);
    Plate("Rodillera "+side,shin,Pos(shin)+new Vector3(0,.01f,.09f),new Vector3(.13f,.14f,.05f),heavy?steel:dark);
    if(role==PlayerClass.Mage)Plate("Tunica frontal "+side,thigh,Vector3.Lerp(Pos(thigh),Pos(shin),.5f)+new Vector3(0,-.04f,.14f),new Vector3(.22f,.52f,.025f),cloth);
   }
   if(role==PlayerClass.Warrior||role==PlayerClass.Tank)Plate("Tabardo",HumanBodyBones.Hips,Pos(HumanBodyBones.Hips)+new Vector3(0,-.08f,.19f),new Vector3(.20f,.34f,.025f),cloth);
   if(role==PlayerClass.Archer){var back=Pos(HumanBodyBones.Chest)+new Vector3(.16f,.05f,-.22f);Shell("Carcaj",HumanBodyBones.Chest,back-Vector3.up*.28f,back+Vector3.up*.25f,.07f,.085f,1,dark);for(int i=0;i<4;i++){var top=back+new Vector3((i-1.5f)*.025f,.38f,0);Shell("Flecha "+i,HumanBodyBones.Chest,top-Vector3.up*.25f,top,.008f,.008f,1,trim,5);Plate("Pluma "+i,HumanBodyBones.Chest,top,new Vector3(.035f,.08f,.01f),cloth);}}
   rig.enabled=true;rig.runtimeAnimatorController=Resources.Load<RuntimeAnimatorController>(role==PlayerClass.Berserker?"Presentation/Human/Berserker":"Presentation/Human/HumanPlayer");PrefabUtility.SaveAsPrefabAsset(actor,root+"/"+role+".prefab");UnityEngine.Object.DestroyImmediate(actor);
  }AssetDatabase.SaveAssets();return "Created six modular humanoid class prefabs with original Avatar";
 }
}

